Q: Calculating average without highest and lowest values in an array A: <pre><code>package Basics;

import java.util.ArrayList;

import java.util.Collections;
import java.util.Scanner;
public class IgnoreLowHighValue {

    public static void main(String[] args) {

        int result =  calculateAverageOfFiveNum(5);
        System.out.println(&quot;The average of sum is &quot; + result);


    }

    // find average of five numbers that takes as user input.
    public static int calculateAverageOfFiveNum(int n) {

        // To store user number input
        ArrayList&lt;Integer&gt; list = new ArrayList&lt;&gt;();

        Scanner scan = new Scanner(System.in);
        int sum = 0;

        //add number into list
        for(int i = 1; i &lt;= n; i++) {
            int num = scan.nextInt();
            list.add(num);
        }

        // take each number from list and find minimum, maximum number and ignore it by using &quot;continue&quot; keyword
        // After that other numbers are adding and store into sum variable.

        for(int num : list) {
            if((Collections.max(list) == num) || (Collections.min(list) == num)) 
                continue;
                sum = sum + num;

        }
        scan.close();

        // find the average of sum by dividing into total n numbers.
        return sum / n;

    }

}
</code></pre>
